-- V108__seed_prestigio.sql — Prestigio (www.prestigio.com.ar), VTEX home-improvement retailer: seed plus the curated leaf mapping.
--
-- Measured 2026-11-19 (legacy API, header `resources`): 2660 products, 2662 in a real scrape (90 s); 2487 once the colour swatches are
-- excluded. Paints, floors, taps, tools, furniture, kitchenware and appliances, plus a few phones, TVs and padel gear: mixed, so rubro_forzado
-- stays NULL and rubro_por_defecto = 'construccion' (as easy); RubroResolver decides by category.
-- The 'Colores' nodes ("Blancos Naturales - Shiitake", "Pauline - Bryant", ~175 rows) are paint-colour swatches sold as products, not goods:
-- ServicioPorNombreDeCategoria excludes them (their children inherit it).
--
-- Leaf mapping: no new categories, curated by hand from the leaf path and a sample of names (fq=C:<id>). The curated leaf outranks the name on this
-- store (NormalizerService.SITIOS_DONDE_LA_HOJA_GANA): "Procesador 400 W" under Procesadoras y Mixer is a kitchen appliance, not a CPU. Left unmapped
-- (the name decides): Infantil, Accesorios (root), Pinturas (root), Iluminacion (root), Paletas y Accesorios (padel racquets, balls and bags share
-- one leaf), Notebooks y Tablets, and the empty parents.
-- One single-line text blob (sitio_key|origen_id|nombre|categoria rows joined by ';', no raw newline: Sonar flags one inside a literal) split by the INSERT, not a literal per row: a string repeated
-- three times is Sonar S1192, and a long VALUES list of near-identical tuples is what Sonar CPD reads as duplicated code.
INSERT INTO sitio (nombre, sitio_key, plataforma, es_premium, rubro_forzado, origen) VALUES
    ('Prestigio', 'prestigio', 'vtex', false, NULL, 'config')
ON CONFLICT (nombre) DO NOTHING;

UPDATE sitio SET rubro_por_defecto = 'construccion' WHERE nombre = 'Prestigio';

WITH linea(l) AS (SELECT regexp_split_to_table('prestigio|121|Vinílicos|Piso;prestigio|122|Adhesivos|Adhesivo;prestigio|123|Terminaciones|Moldura;prestigio|126|Látex|Pintura;prestigio|127|Esmaltes|Pintura;prestigio|128|Impermeabilizantes|Impermeabilizante;prestigio|129|Productos para madera|Pintura;prestigio|130|Revestimientos texturados|Revestimiento;prestigio|131|Pisos y Deck|Pintura;prestigio|132|Pintura para piletas|Pintura;prestigio|133|Preparación de superficies|Pintura;prestigio|152|Sillas de Interior|Silla;prestigio|153|Mesas de Comedor|Mesa;prestigio|155|Colchones y Sommiers|Colchón;prestigio|158|Banquetas y Taburetes|Silla;prestigio|167|Iluminación|Iluminación;prestigio|172|Mantenimiento de Piletas|Químico de Pileta;prestigio|173|Sombrillas, Gazebos y Redes|Gazebo y Sombrilla;prestigio|182|Monitores|Monitor;prestigio|190|Jarros y Termos|Bazar;prestigio|191|Accesorios de Cocina|Bazar;prestigio|193|Parrillas y Hornos|Parrilla;prestigio|200|Decks|Piso;prestigio|204|Griferías|Grifería;prestigio|207|Complementos para baño|Accesorio de Baño;prestigio|214|Piletas estructurales e inflables|Pileta;prestigio|216|Sillones de exterior|Mueble de Exterior;prestigio|217|Juegos de exterior|Mueble de Exterior;prestigio|218|Camping y Playa|Mueble de Exterior;prestigio|229|Cocción y Horneado|Bazar;prestigio|231|Heladeras|Heladera;prestigio|234|Freezer|Heladera;prestigio|242|Mesas bajas, barras y recibidoras|Mesa;prestigio|246|Organizadores|Caja y Canasto;prestigio|257|Pinceles, rodillos y bandejas|Accesorio de Pintura;prestigio|258|Cintas|Cinta Adhesiva;prestigio|259|Diluyentes|Diluyente;prestigio|260|Elementos de seguridad|Protección Personal;prestigio|261|Escaleras|Escalera;prestigio|262|Espátulas, llanas y cepillos|Herramienta Manual;prestigio|263|Lijas y abrasivos|Lija;prestigio|264|Limpieza|Artículo de Limpieza;prestigio|265|Selladores y adhesivos|Adhesivo;prestigio|270|Aires Acondicionados|Aire Acondicionado;prestigio|272|Ventiladores|Ventilador;prestigio|274|Celulares|Celular;prestigio|277|TV|TV y Audio;prestigio|278|Audio y Sonido|TV y Audio;prestigio|279|Lavarropas|Lavarropas;prestigio|280|Secarropas|Lavarropas;prestigio|281|Lavavajillas|Lavarropas;prestigio|282|Aspiradoras y limpiadoras|Aspiradora;prestigio|283|Licuadoras|Pequeño Electrodoméstico;prestigio|284|Cafeteras|Pequeño Electrodoméstico;prestigio|285|Exprimidores y extractores|Pequeño Electrodoméstico;prestigio|286|Freidoras|Pequeño Electrodoméstico;prestigio|287|Hornos y anafes|Cocina y Horno;prestigio|288|Microondas|Cocina y Horno;prestigio|289|Pavas y Termos electricos|Pequeño Electrodoméstico;prestigio|290|Planchas|Pequeño Electrodoméstico;prestigio|291|Procesadoras y Mixer|Pequeño Electrodoméstico;prestigio|292|Sandwicheras y Wafleras|Pequeño Electrodoméstico;prestigio|293|Vaporera y Robot de cocina|Pequeño Electrodoméstico;prestigio|294|Hornos|Cocina y Horno;prestigio|295|Anafes|Cocina y Horno;prestigio|296|Cocinas|Cocina y Horno;prestigio|297|Campanas y Purificadores|Campana y Extractor;prestigio|311|Sillones, Poltronas y Puff|Sillón;prestigio|312|Entonadores y Tintas|Pintura;prestigio|329|Reposeras|Reposera y Hamaca;prestigio|330|Mesas y Sillas auxiliares|Mesa;prestigio|331|Sillas de exterior|Silla;prestigio|332|Mesas de exterior|Mesa;prestigio|333|Batidoras|Pequeño Electrodoméstico;prestigio|334|Casetas|Depósito de Jardín;prestigio|335|Cuidado personal|Pequeño Electrodoméstico;prestigio|336|Aerosoles|Pintura;prestigio|337|Wall Panels|Wall Panel;prestigio|338|Eléctrica|Calefactor;prestigio|339|A leña|Calefactor;prestigio|340|Tostadora|Pequeño Electrodoméstico;prestigio|341|Consolas|Consola;prestigio|342|Camaras y accesorios|Cámara;prestigio|349|Preparación|Bazar;prestigio|350|Cocción|Bazar;prestigio|351|Cafe y Té|Bazar;prestigio|353|Lavado|Artículo de Limpieza;prestigio|354|Contenedores de alimentos|Bazar;prestigio|355|Organización del hogar|Caja y Canasto;prestigio|356|Complementos de baño|Accesorio de Baño;prestigio|357|Decoración|Decoración;prestigio|359|Vajilla|Bazar;prestigio|360|Vasos, copas y jarras|Bazar;prestigio|361|Cubiertos|Bazar;prestigio|362|Cacerolas y sartenes|Bazar;prestigio|363|Termos y Vasos Térmicos|Bazar;prestigio|364|Muebles y Racks de TV|Mueble', ';')),
campo(f) AS (SELECT string_to_array(l, '|') FROM linea)
INSERT INTO sitio_categoria (sitio_key, origen_id, nombre, categoria)
SELECT f[1], f[2]::int, f[3], f[4] FROM campo
ON CONFLICT (sitio_key, origen_id) DO UPDATE SET categoria = EXCLUDED.categoria;
